  def tokenizeDouble(value: Double): Token =
    Token(f"$value%.${precision}f", TokenType.Numeric, Map("original_type" -> "Double"))

  def tokenize(value: BigDecimal): Token =
    Token(value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString, TokenType.Numeric, Map("original_type" -> "BigDecimal"))
}

/**
 * Tokenizer for date/time types.
 */
class TemporalTokenizer(
  formatStr: Option[String] = None
) extends Tokenizer[LocalDateTime] {

  private val isoFormatter = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val dateFormatter = DateTimeFormatter.ISO_LOCAL_DATE
  private val customFormatter = formatStr.map(DateTimeFormatter.ofPattern)

  def tokenize(value: LocalDateTime): Token = {
    val formatter = customFormatter.getOrElse(isoFormatter)
    Token(formatter.format(value), TokenType.Temporal)
  }

  def tokenizeDate(value: LocalDate): Token = {
    val formatter = customFormatter.getOrElse(dateFormatter)
    Token(formatter.format(value), TokenType.Temporal)
  }
}

/**
 * Registry with complex nested generic types.
 */
class TokenRegistry[T] {
  private var _registry: Map[String, TokenContainer[T]] = Map.empty
  private var _handlers: List[T => Option[Token]] = List.empty

  def register(key: String, container: TokenContainer[T]): Unit =
    _registry = _registry + (key -> container)

  def addHandler(handler: T => Option[Token]): Unit =
    _handlers = _handlers :+ handler

  def process(key: String): List[Option[Token]] =
    _registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        val results = scala.collection.mutable.ListBuffer.empty[Option[Token]]
        for (item <- container.getAll) {
          val processed = _handlers.collectFirst {
            case handler if handler(item).isDefined => handler(item)
          }.flatten
          results += processed
        }
        results.toList
    }
}

