sealed trait JsonValue
object JsonValue {
  case class StringValue(value: String) extends JsonValue
  case class NumberValue(value: BigDecimal) extends JsonValue
  case class BooleanValue(value: Boolean) extends JsonValue
  case object NullValue extends JsonValue
  case class ArrayValue(values: List[JsonValue]) extends JsonValue
  case class ObjectValue(fields: Map[String, JsonValue]) extends JsonValue
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = valueToString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  private def valueToString(value: JsonValue): String = value match {
    case StringValue(s) => s"\"$s\""
    case NumberValue(n) => n.toString
    case BooleanValue(b) => b.toString
    case NullValue => "null"
    case ArrayValue(values) =>
      val items = values.map(valueToString).mkString(", ")
      s"[$items]"
    case ObjectValue(fields) =>
      val items = fields.map { case (k, v) => s"\"$k\": ${valueToString(v)}" }.mkString(", ")
      s"{$items}"
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    val result = parts.foldLeft[Option[JsonValue]](Some(value)) { (current, part) =>
      current.flatMap { v =>
        v match {
          case ObjectValue(fields) => fields.get(part)
          case ArrayValue(values) if part.forall(_.isDigit) =>
            val idx = part.toInt
            if (idx >= 0 && idx < values.length) Some(values(idx)) else None
          case _ => None
        }
      }
    }
    result.map(tokenize)
  }
}

